#!/usr/bin/env bash
# Vendors the generated Fanous theme registry (Kotlin) from the monorepo at the commit pinned in fanous.lock.
#   scripts/sync-fanous.sh            write the file
#   scripts/sync-fanous.sh --check    fail if the vendored file differs from the pinned commit (CI)
# The registry is generated by packages/fanous-tokens (`pnpm tokens:generate`); never edit it here.
set -euo pipefail
cd "$(dirname "$0")/.."
read -r REPO SHA < fanous.lock
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
git -c advice.detachedHead=false clone -q --filter=blob:none --no-checkout "https://github.com/$REPO.git" "$WORK/src"
git -C "$WORK/src" sparse-checkout set --no-cone /packages/fanous-tokens/generated/native/kotlin
git -C "$WORK/src" checkout -q "$SHA"
SOURCE="$WORK/src/packages/fanous-tokens/generated/native/kotlin/net/alummahnow/fanous/FanousThemes.kt"
TARGET=design/src/main/kotlin/net/alummahnow/fanous/FanousThemes.kt
if [[ "${1:-}" == "--check" ]]; then
  if ! diff -q "$SOURCE" "$TARGET" >/dev/null; then
    echo "$TARGET differs from $REPO@$SHA. Run scripts/sync-fanous.sh." >&2
    exit 1
  fi
  echo "Fanous registry matches $REPO@$SHA."
  exit 0
fi
mkdir -p "$(dirname "$TARGET")"
cp "$SOURCE" "$TARGET"
echo "Vendored the Fanous registry from $REPO@$SHA."
